<body>
<!-- 不把捕获到的 JSON 拼进 HTML；从本 iframe 对应的楼层读取原始数据。 -->
<div class="kami-root" data-kami-comp="search" data-kami-search="1" data-kami-container="embedded">
  <div class="kami-shell kami-surface kami-collapse" data-kami-open="0">
    <div class="kami-head kami-collapse-head" role="button" tabindex="0" aria-expanded="false" aria-controls="search-body">
      <span class="kami-dot" aria-hidden="true"></span>
      <span class="kami-deco" data-kami-deco="d20" aria-hidden="true"></span>
      <span class="kami-title">搜索资料</span>
      <span class="kami-badge" data-kami-kind="info" data-search-origin hidden></span>
      <span class="kami-actions">
        <span class="kami-sub" data-search-count>读取中</span>
        <span class="kami-chev" aria-hidden="true">▸</span>
      </span>
    </div>
    <div id="search-body" class="kami-body kami-collapse-body">
      <p class="kami-card-note" data-search-scope hidden></p>
      <ol class="kami-facts" data-search-facts></ol>
      <div class="kami-src-box" data-search-sources hidden>
        <span class="kami-sub kami-src-label">来源</span>
        <ol class="kami-src-list" data-search-source-list></ol>
      </div>
      <p class="kami-card-note" data-search-empty hidden></p>
    </div>
  </div>
</div>
<script>
(function(){
  'use strict';
  /* 正则前端（src/regex/frontend-*.html，跑在酒馆助手的消息 iframe 里）建元素用的小工具，构建期整段内联（占位见 build/kami-doc.mjs 的 expandUi）。
 * 2026-11-04 起取代旧组件核心 src/ui/core.js（连同旧运行库一起删了），正则前端只用到它的 element() 与 adopt()。
 * 两者照旧给元素打 data-kami-ui / data-kami-card-role 标记——同一份兜底样式（src/ui/foundation.css + src/skin/base.css，
 * 构建期内联进前端文档）按这些标记写规则。
 * ES5、不依赖运行库。 */
