    Object.keys(values || {}).forEach(function (name) {
      var value = values[name], lower = name.toLowerCase();
      if (/^on/.test(lower) || lower === 'innerhtml' || lower === 'outerhtml' || lower === 'srcdoc') { throw new Error('组件属性禁止执行代码'); }
