/* ---- 事实列表：一行一条，左侧编号 ---- */
html:not([data-kami-skin]) .kami-root[data-kami-comp="search"] .kami-facts {
  display: flex;
  flex-direction: column;
  gap: var(--kami-gap);
  margin: 0;
  padding: 0;
  list-style: none;
