 */
(function () {
  var SKINS_NEXT = [{"manifest":{"id":"suiguang","name":"碎光","version":"0.2.0","contract":"1.0","description":"静时如纸，动时碎光。宣纸 / 墨 / 阅读三档，青瓷色点睛；打开时碎块聚合成边，关闭时碎散，按下时局部碎裂，缝隙里透出光。","author":"卡密预设","credits":"纸纹由 build/frontend/make-paper-texture.mjs 程序生成，无第三方素材。","defaultScheme":"light","schemes":{"light":{"seeds":{"neutral":"#ebe5d8","accent":"#3b7a68","radius":6,"elevation":"shadow","font":{"heading":""Songti SC", "Noto Serif CJK SC", "Source Han Serif SC", STSong, SimSun, Georgia, serif"},"danger":"#b5523d","warning":"#a87a2a","success":"#4f7f50","info":"#456c88"},"components":{"badge":{"tone":"accent-soft"}},"tokens":{"selected":"#dfe7dd"}},"dark":{"seeds":{"neutral":"#23211d","accent":"#79b8a4","radius":6,"elevation":"shadow","font":{"heading":""Songti SC", "Noto Serif CJK SC", "Source Han Serif SC", STSong, SimSun, Georgia, serif"},"danger":"#e08a74","warning":"#d9b06a","success":"#8fbf8b","info":"#8fb1c9"},"components":{"badge":{"tone":"accent-soft"}},"tokens":{"selected":"#2f3c37"}},"reading":{"base":"light","name":"阅读","seeds":{"neutral":"#ecdfc3","accent":"#7a5230","radius":6,"elevation":"flat","danger":"#a24a35","warning":"#8f6a24","success":"#4f7348","info":"#4a6478","font":{"heading":""Songti SC", "Noto Serif CJK SC", "Source Han Serif SC", STSong, SimSun, Georgia, serif"}},"tokens":{"selected":"#e3d3b2"},"components":{"badge":{"tone":"accent-soft"}}}},"modules":["fracture"],"effects":[{"id":"fracture","name":"碎光","description":"按下、展开、弹出时，组件边缘碎成方块飞散，缝隙里透出强调色的光。","group":"动效","default":true},{"id":"paper","name":"纸纹","description":"浅色档的表面铺一层很淡的宣纸纤维纹理（静态）。","group":"质感","default":true},{"id":"seal","name":"印章","description":"面板标题前、卡片角上的小方块标记。","group":"装饰","default":true}],"params":[{"id":"glow","name":"溢光强度","type":"number","default":0.7,"min":0.2,"max":1,"step":0.05,"bind":"var:--k-skin-glow","group":"动效"},{"id":"shard","name":"碎块大小","type":"number","default":6,"min":3,"max":12,"step":1,"unit":"px","bind":"var:--k-skin-shard","group":"动效"},{"id":"corner","name":"圆角","type":"number","default":6,"min":0,"max":12,"step":1,"bind":"seed:radius","group":"形状"}],"assets":{"paper":{"file":"assets/paper.png","alt":"宣纸纹理"}},"ornaments":["panel-head-start","card-corner"],"flavor":{},"icons":{"🔻":"section-end","🔺":"section-start","⚔️":"swords","🚫":"ban","🧩":"puzzle","🐱":"cat","📌":"pin","🔞":"flame","🍺":"beer","🗣️":"languages","👁️":"eye","🎯":"target","💬":"message","💤":"moon","🏃‍♂️":"footprints","🎮":"gamepad","🔊":"volume","💭":"brain","❌":"x","🪓":"zap","🐋":"fish","💕":"heart","⚙️":"settings","🎛":"sliders","‼️":"alert","📖":"book","😀":"smile","📝":"pen-line","🌐":"globe","🎭":"drama","🧪":"sparkles","🧠":"brain","🔧":"wrench","📋":"list","🤖":"bot","🌒":"moon-star","✒️":"feather","💀":"skull","🔄":"refresh","🖊️":"pen","🌊":"waves","😄":"laugh","🎆":"sparkle","🎬":"clapperboard","🗿":"mountain","😘":"heart-hands","😔":"rain","🪔":"lamp","🌌":"orbit","🔪":"knife","👊":"fist","💗":"heart","😭":"frown","🔫":"crosshair","🦇":"bird","🐙":"telescope","📕":"book-marked","👻":"ghost","😏":"glasses","🌺":"flower","🔝":"section-start","🔛":"layers","🎥":"video","🎨":"palette","🔚":"section-end","🧱":"bricks","🔠":"letters","👥":"users","🗂️":"folder","💫":"sparkles","☑️":"check","🥊":"fist","📚":"library","📜":"scroll","🔀":"shuffle","🔮":"gem","☯️":"yin-yang","🤔":"help","♿":"accessibility","🎲":"dice"}},"css":"/* 碎光 —— 静时如纸，动时碎光。
   静态：发丝细边、柔和的纸面层次、衬线标题；方块是贯穿的母题（印章、方形开关钮）。
   动态：碎裂溢光由平台模块 fracture 负责（JS、对象池、只动 transform / opacity），这里只给参数和「碎裂中」的边缘状态。 */

/* ───────── 动效参数（交给 fracture 模块读） ───────── */
:host, [data-k-surface] {
  --k-fx-size: var(--k-skin-shard, 6px);
  --k-fx-strength: var(--k-skin-glow, .7);
  --k-fx-glow: var(--k-accent);
  --k-fx-spread: 22px;
}
/* 溢光用更亮的「发光色」：浅色档如果用深青瓷绿，在纸面上读起来像阴影而不是光 */
[data-k-surface][data-k-scheme="light"] { --k-fx-glow: #49d3a6; }
[data-k-surface][data-k-scheme="dark"] { --k-fx-glow: #8ff0cc; }

/* ───────── 排版 ───────── */
[data-k-surface] { letter-spacing: .01em; }
[data-k="panel"] > [data-k-part="head"] > [data-k-part="title"], [data-k="dialog"][data-k-part="content"] > [data-k-part="head"] > [data-k-part="title"], [data-k="card"] > [data-k-part="head"] > [data-k-part="title"] { letter-spacing: .04em; }

/* ───────── 表面：少框线。层次靠底色差与间距，只有浮在酒馆上面的面板 / 对话框留一圈发丝线 ───────── */
[data-k="card"] { border-color: transparent; box-shadow: none; }
[data-k="card"][data-role="choice"] { border: 1.5px solid transparent; }
[data-k="card"][data-role="choice"][data-state="selected"] { border: 1.5px solid var(--k-accent); }
[data-k="panel"], [data-k="dialog"][data-k-part="content"] { border-color: var(--k-divider); }
[data-k="panel"] > [data-k-part="head"], [data-k="panel"] > [data-k-part="foot"], [data-k="dialog"][data-k-part="content"] > [data-k-part="head"], [data-k="dialog"][data-k-part="content"] > [data-k-part="foot"] { border-color: transparent; }
[data-k="tabs"] [data-k-part="list"] { border-bottom-color: transparent; }

/* ───────── 按钮：略方的圆角，按下时轻压 ───────── */
[data-k="button"] { border-radius: var(--k-r-sm); font-weight: 500; letter-spacing: .03em; transition: background-color var(--k-dur-fast) var(--k-ease), border-color var(--k-dur-fast) var(--k-ease), transform var(--k-dur-fast) var(--k-ease); }
[data-k="button"]:active:not(:disabled), [data-k="icon-button"]:active:not(:disabled) { transform: translateY(1px) scale(.98); }
[data-k="card"][data-role="choice"]:active { transform: scale(.99); }

/* 碎裂进行中：边缘「碎掉」——边线暂时隐去，交给飞散的碎块与溢光 */
[data-k][data-k-fx="active"] { border-color: transparent; }
[data-k="card"][data-role="choice"][data-state="selected"][data-k-fx="active"] { border-color: var(--k-accent); }

/* 选择卡在能悬停的设备上：底色微微抬一档提示可点 */
@media (hover: hover) and (pointer: fine) {
  [data-k="card"][data-role="choice"]:not([data-state="selected"]):hover { border-color: var(--k-divider); }
}

/* 能悬停的设备（PC）：悬停时边缘亮一线强调色；触屏不做悬停态，避免「点完还亮着」 */
@media (hover: hover) and (pointer: fine) {
  [data-k="button"]:not([data-variant="primary"]):not(:disabled):hover, [data-k="select"][data-k-part="trigger"]:hover, [data-k="card"][data-role="choice"]:hover {
    box-shadow: 0 0 0 1px var(--k-focus-ring);
  }
}

/* 触屏（手机）：更大的点按区域与间距，页签更好点 */
@media (pointer: coarse) {
  [data-k="tabs"] [data-k-part="tab"] { padding: var(--k-space-3) var(--k-space-4); }
  [data-k="card"] > [data-k-part="head"] { padding: var(--k-space-4); }
  [data-k="field"] { gap: var(--k-space-3); }
}

/* ───────── 开关 / 复选框：方块母题 ───────── */
[data-k="switch"] { border-radius: var(--k-r-sm); }
[data-k="switch"] [data-k-part="thumb"] { border-radius: var(--k-r-xs); }
[data-k="checkbox"] { border-radius: 2px; }

/* ───────── 页签：当前页下面一条细线，两端各一个小方块 ───────── */
[data-k="tabs"] [data-k-part="tab"][data-state="active"] { border-bottom-width: 2px; }

/* ───────── 印章装饰 ───────── */
[data-k-surface][data-k-effects~="seal"] [data-k-ornament="panel-head-start"] {
  display: inline-block; flex: none; width: 8px; height: 8px; margin-right: 2px;
  background: var(--k-accent); box-shadow: 3px 3px 0 var(--k-accent-soft);
}
[data-k-surface][data-k-effects~="seal"] [data-k="card"][data-role="container"]::after {
  content: ''; position: absolute; right: 10px; top: 10px; width: 4px; height: 4px; background: var(--k-accent); opacity: .7; pointer-events: none;
}

/* ───────── 纸纹（只在浅色档）：静态纹理，不动画 ───────── */
[data-k-surface][data-k-scheme="light"][data-k-effects~="paper"] [data-k-level="bg"],
[data-k-surface][data-k-scheme="light"][data-k-effects~="paper"] [data-k-level="surface-1"] {
  background-image: var(--k-asset-paper);
  background-size: 96px 96px;
}

/* ───────── 加载：几个小方块循环聚散（与碎光同源的皮肤语言）；动效关闭时由平台停掉循环 ───────── */
[data-k="spinner"] { border: 0; border-radius: 0; width: 1em; height: 1em; animation: none; }
[data-k="spinner"]::before, [data-k="spinner"]::after {
  content: ''; position: absolute; width: 38%; height: 38%; background: currentColor;
  animation: k-suiguang-gather 1.1s var(--k-ease) infinite;
}
[data-k="spinner"]::before { left: 0; top: 0; box-shadow: 0.62em 0.62em 0 currentColor; }
[data-k="spinner"]::after { right: 0; top: 0; box-shadow: -0.62em 0.62em 0 currentColor; animation-delay: -0.55s; opacity: .55; }
@keyframes k-suiguang-gather { 0%, 100% { transform: scale(1); } 50% { transform: scale(.45) rotate(45deg); } }

/* ───────── 阅读档：更低的纸面对比、无纸纹（纸色本身就是暖的） ───────── */
[data-k-surface][data-k-scheme="reading"] { --k-fx-glow: #e0a35c; }

/* ───────── 消息前端：正文无框；边注一条左侧细线 + 次要色；选项是无框列表（前端重构-消息前端方案 第三节）───────── */
/* 底：一张很淡的纸（浅色档有纸纹），不描边；与酒馆背景拉开即可 */
[data-k="msg-view"] { box-shadow: 0 1px 0 var(--k-divider); }
/* 正文用衬线：读长文更有纸感；对白略重、引号退后；心理描写用楷体（系统没有楷体时退回衬线） */
[data-k-content="body"] > * { font-family: "Songti SC", "Noto Serif CJK SC", "Source Han Serif SC", STSong, SimSun, Georgia, serif; letter-spacing: .02em; }
/* 皮肤自己的字体颜色（显示面板「皮肤字体颜色」开着时用；关掉时由 lock.css 换成酒馆的 Quote / Em 颜色）：
   对白用青瓷色（与强调色同族、压深一档保证正文对比度），心理描写用淡墨 */
[data-k-surface][data-k-scheme="light"] { --k-msg-dialogue: #2c6a58; --k-msg-thought: #6b6356; }
[data-k-surface][data-k-scheme="dark"] { --k-msg-dialogue: #9ccfbd; --k-msg-thought: #aaa294; }
[data-k-surface][data-k-scheme="reading"] { --k-msg-dialogue: #7a4520; --k-msg-thought: #6a5c49; }
[data-k-content] [data-k-part="thought"] { font-style: normal; font-family: "Kaiti SC", STKaiti, KaiTi, "楷体", "AR PL UKai CN", "Noto Serif CJK SC", serif; }
[data-k-content] [data-k-part="term"] { text-decoration-color: var(--k-accent); text-decoration-thickness: 1px; text-decoration-style: dotted; }
/* 场景转换：一枚小方块（印章母题）代替横线 */
[data-k-content="body"] > [data-k-part="scene-break"] { width: 6px; height: 6px; border: 0; background: var(--k-accent); opacity: .55; transform: rotate(45deg); }
/* 流式光标：方块，和碎光同源 */
[data-k-content] [data-k-part="caret"] { border-radius: 1px; box-shadow: 0 0 6px var(--k-fx-glow); }

:is([data-k="msg-think"], [data-k="msg-search"]) > [data-k-part="fold"] > [data-k-part="body"] { border-left: 1.5px solid var(--k-divider); }
[data-k="msg-think"][data-streaming] > [data-k-part="head"] > [data-k-part="toggle"] { color: var(--k-on); }

[data-k="msg-options"] > [data-k-part="head"] > [data-k-part="title"] { letter-spacing: .06em; }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"] { border: 1px solid transparent; }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"]:active { transform: scale(.995); }
@media (hover: hover) and (pointer: fine) {
