:host, [data-k-surface] { --k-fx-words: "ドキッ キュン ♥ きゃー ドキドキ"; --k-amb: glyph; --k-amb-glyphs: "♡ ♥ ✿"; --k-amb-dir: up; --k-amb-count: 9; --k-amb-speed: 15; --k-amb-size: 7; --k-amb-color: var(--k-accent); --k-amb-alpha: .26; }

