/* ───────── 按钮：小直角，主按钮像压了金边的皮质标签 ───────── */
[data-k="button"] { border-radius: 2px; font-family: var(--k-font-heading); letter-spacing: .05em; }
[data-k="button"][data-variant="primary"] { box-shadow: inset 0 0 0 1px rgba(255, 220, 150, .35), 0 1px 0 var(--k-quest-ink); }
[data-k="button"]:active:not(:disabled), [data-k="icon-button"]:active:not(:disabled) { transform: translateY(1px); }

/* ───────── 页签：像书页侧边的索引签 ───────── */
[data-k="tabs"] [data-k-part="tab"] { font-family: var(--k-font-heading); border-radius: 4px 4px 0 0; }
