[data-k-surface][data-k-motion="full"] [data-k-ornament="panel-head-start"] { animation: k-quest-needle 9s ease-in-out infinite; }
@keyframes k-quest-needle { 0%, 100% { transform: rotate(-8deg); } 50% { transform: rotate(8deg); } }

