:host, [data-k-surface] { --k-fx-lock: out; --k-amb: blink; --k-amb-count: 12; --k-amb-speed: 6; --k-amb-size: 3; --k-amb-color: var(--k-fx-glow); --k-amb-alpha: .7; }

