[data-k-content="body"] > [data-k-part="scene-break"] { width: 70%; border: 0; height: 2px; background: linear-gradient(90deg, transparent, var(--k-jh-ink) 30%, var(--k-jh-ink) 70%, transparent); transform: rotate(-4deg); }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"] { border: 0; border-left: 3px solid var(--k-jh-ink); border-radius: 0; }

/* ═══════════ 深化（2026-11-02，世界观皮肤系列方案 第五节） ═══════════ */
/* 核心隐喻：武林卷轴与刀光。招牌：斜刀光（slash）+ 墨晕；环境：竹叶斜落 */
:host, [data-k-surface] { --k-amb: petal; --k-amb-dir: down; --k-amb-angle: 22; --k-amb-count: 7; --k-amb-speed: 13; --k-amb-size: 7; --k-amb-color: #4f6e3c; --k-amb-alpha: .35; }
[data-k-surface][data-k-scheme="dark"] { --k-amb-color: #7f9e6a; --k-amb-alpha: .3; }

/* 开关 = 刀鞘：漆黑鞘身两道金箍，滑块是一枚朱印（打开时） */
[data-k="switch"] { background: linear-gradient(90deg, transparent 22%, #b08a3a 22% 26%, transparent 26% 74%, #b08a3a 74% 78%, transparent 78%), var(--k-jh-ink); border-color: var(--k-jh-ink); }
[data-k="switch"][data-state="checked"] { background: linear-gradient(90deg, transparent 22%, #d8b060 22% 26%, transparent 26% 74%, #d8b060 74% 78%, transparent 78%), var(--k-jh-cinnabar); border-color: var(--k-jh-cinnabar); }
[data-k="switch"] [data-k-part="thumb"] { background: var(--k-bg); box-shadow: inset 0 0 0 2px var(--k-jh-cinnabar); }
/* 进度 = 一笔浓墨：尾端飞白 */
[data-k="progress"] { height: 5px; border-radius: 0; background: var(--k-jh-wash); box-shadow: none; }
[data-k="progress"] > [data-k-part="indicator"] { border-radius: 0; background: linear-gradient(90deg, var(--k-jh-ink) 70%, color-mix(in srgb, var(--k-jh-ink) 40%, transparent)); }
/* 滑块 = 墨点 */
[data-k="slider"] > [data-k-part="track"] > [data-k-part="thumb"] { background: var(--k-jh-ink); border-radius: 46% 54% 50% 50%; box-shadow: 0 0 0 3px var(--k-jh-wash); }

/* 选中的选择卡：右下角盖一方朱印「准」 */
[data-k="card"][data-role="choice"][data-state="selected"] > [data-k-ornament="card-corner"] { display: grid; place-items: center; right: 8px; bottom: 8px; width: 26px; height: 26px; background: var(--k-jh-cinnabar); color: #fff8ef; font: 400 15px/1 "Ma Shan Zheng", "Kaiti SC", KaiTi, serif; box-shadow: inset 0 0 0 2px #fff8ef, inset 0 0 0 3px var(--k-jh-cinnabar); transform: rotate(-6deg); }
[data-k="card"][data-role="choice"][data-state="selected"] > [data-k-ornament="card-corner"]::before { content: '准'; }
[data-k-surface][data-k-motion="full"] [data-k="card"][data-role="choice"][data-state="selected"] > [data-k-ornament="card-corner"] { animation: k-jh-seal .35s cubic-bezier(.3, 1.6, .5, 1) both; }
@keyframes k-jh-seal { from { transform: scale(2) rotate(-14deg); opacity: 0; } to { transform: scale(1) rotate(-6deg); opacity: 1; } }

