[data-k-content] [data-k-part="caret"] { box-shadow: 0 0 8px var(--k-accent); }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"] { border-radius: 0; border: 1px solid color-mix(in srgb, var(--k-neon-cyan) 40%, transparent); }

