/* 进度 = 信号格 */
[data-k="progress"] { height: 10px; border-radius: 0; background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--k-on) 12%, transparent) 0 6px, transparent 6px 8px); box-shadow: none; }
