[data-k="slider"] > [data-k-part="track"] > [data-k-part="thumb"] { border-radius: 0; background: var(--k-neon-cyan); box-shadow: 0 0 8px var(--k-neon-cyan); }
/* 徽章 = 全息贴纸（强调色那枚） */
[data-k="badge"][data-tone="accent"] { background: linear-gradient(115deg, #7af7ff, #ff8ac4 50%, #fff36a); color: #111; }

/* 卡片右下：一截条形码 */
[data-k="card"] > [data-k-ornament="card-corner"] { display: block; right: 8px; bottom: 6px; width: 34px; height: 9px; background: repeating-linear-gradient(90deg, var(--k-on) 0 1px, transparent 1px 3px, var(--k-on) 3px 5px, transparent 5px 6px, var(--k-on) 6px 7px, transparent 7px 9px); opacity: .35; }
[data-k="card"][data-role="choice"][data-state="selected"] > [data-k-ornament="card-corner"] { background: repeating-linear-gradient(90deg, var(--k-neon-cyan) 0 1px, transparent 1px 3px, var(--k-neon-cyan) 3px 5px, transparent 5px 6px, var(--k-neon-cyan) 6px 7px, transparent 7px 9px); opacity: .9; }

/* 面板背景：竖排霓虹招牌字（夜市 / 電脳）贴着右边，下方一道地平线辉光 */
