[data-k="panel"] > [data-k-ornament="surface-backdrop"]::after, [data-k="dialog"][data-k-part="content"] > [data-k-ornament="surface-backdrop"]::after { content: ''; position: absolute; left: 0; right: 0; bottom: 0; height: 90px; background: linear-gradient(0deg, color-mix(in srgb, var(--k-accent) 18%, transparent), transparent); }
[data-k="msg-view"] > [data-k-ornament="surface-backdrop"] { display: block; }
[data-k="msg-view"] > [data-k-ornament="surface-backdrop"]::before { content: 'ネオン'; position: absolute; right: 6px; top: 8px; writing-mode: vertical-rl; font: 900 38px/1 var(--k-font-heading); color: transparent; -webkit-text-stroke: 1px var(--k-neon-cyan); opacity: .12; }
[data-k-surface][data-k-motion="full"] [data-k="panel"] > [data-k-ornament="surface-backdrop"]::before, [data-k="dialog"][data-k-part="content"] > [data-k-ornament="surface-backdrop"]::before { animation: k-neon-flick 7s steps(1) infinite; }

