/* ───────── 直角 + 细金线；面板上下各一道双金线（像檐口） ───────── */
[data-k="panel"], [data-k="dialog"][data-k-part="content"], [data-k="card"], [data-k="button"], [data-k="select"][data-k-part="trigger"], [data-k="text-field"], [data-k="text-area"], [data-k="badge"] { border-radius: 0; }
