[data-k="card"][data-role="choice"][data-state="selected"] { border-left-width: 3px; border-right-width: 3px; border-color: var(--k-accent); }
[data-k="panel"] > [data-k-part="head"], [data-k="dialog"][data-k-part="content"] > [data-k-part="head"] { border-bottom: 1px solid var(--k-laurel-gold); justify-content: center; }
[data-k="panel"] > [data-k-part="head"] > [data-k-part="title"], [data-k="dialog"][data-k-part="content"] > [data-k-part="head"] > [data-k-part="title"], [data-k="card"] > [data-k-part="head"] > [data-k-part="title"], [data-k="setting-section"] > [data-k-part="head"] > [data-k-part="title"] { text-transform: uppercase; letter-spacing: .22em; font-weight: 600; }

/* ───────── 按钮：大写宽字距，金线框 ───────── */
[data-k="button"] { text-transform: uppercase; letter-spacing: .18em; font-family: var(--k-font-heading); }
[data-k="button"]:not([data-variant="primary"]) { border-color: var(--k-laurel-gold); }
[data-k="button"]:active:not(:disabled), [data-k="icon-button"]:active:not(:disabled) { transform: translateY(1px); }
