/* 月桂开关：容器卡底部中间一枚小叶环 */
[data-k-surface][data-k-effects~="laurel"] [data-k="card"][data-role="container"]::after { content: ''; position: absolute; left: 50%; bottom: 4px; width: 26px; height: 10px; translate: -50% 0; pointer-events: none; opacity: .45; background: radial-gradient(circle, var(--k-laurel-gold) 1.5px, transparent 2px) center / 6px 10px repeat-x; }

[data-k="spinner"] { border-radius: 0; border-color: color-mix(in srgb, var(--k-laurel-gold) 30%, transparent); border-top-color: var(--k-laurel-gold); }

/* ───────── 消息正文：衬线，首行缩进；对白紫红，心理描写石灰色 ───────── */
[data-k-content="body"] > * { font-family: "Songti SC", "Noto Serif CJK SC", "Source Han Serif SC", Georgia, serif; letter-spacing: .02em; }
