[data-k-ornament="panel-head-start"], [data-k-ornament="panel-head-end"] { width: 36px; height: 22px; }
/* 页签 = 立柱之间：每个页签左右各一道金线（柱），当前页签顶上一条横楣 */
[data-k="tabs"] [data-k-part="tab"] { box-shadow: inset 1px 0 0 color-mix(in srgb, var(--k-laurel-gold) 40%, transparent), inset -1px 0 0 color-mix(in srgb, var(--k-laurel-gold) 40%, transparent); }
