/* 徽章 = 钱币 */
[data-k="badge"][data-tone="accent"] { border-radius: var(--k-r-pill); background: radial-gradient(circle at 35% 30%, #fbe6a8, #d8b45e 55%, #a07a2a); color: #2a1e08; box-shadow: inset 0 0 0 1px #8a6a20; }
/* 进度 = 刻痕：轨道刻满小格，填充是金箔 */
[data-k="progress"] { height: 8px; border-radius: 0; background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--k-laurel-gold) 30%, transparent) 0 1px, transparent 1px 10px), var(--k-sunken); }
