/* 开关 = 大理石槽里一枚金币 */
[data-k="switch"] { border-radius: 0; }
[data-k="switch"] [data-k-part="thumb"] { border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fbe6a8, #d8b45e 55%, #a07a2a); box-shadow: 0 0 0 1px #8a6a20; }
