   极细标题、加大字距、数字等宽；HUD 角标 ⌜⌟ 与数据读数；打开时线条逐笔描出（trace corner）。与霓虹区别：干净、不故障。 */

:host, [data-k-surface] { --k-fx-trace: corner; --k-fx-glow: #0a6cd6; }
[data-k-surface][data-k-scheme="dark"] { --k-fx-glow: #4cc9f0; }
[data-k-surface] { --k-grid-line: rgba(10, 108, 214, .28); --k-grid-dot: rgba(10, 108, 214, .14); --k-grid-glass: rgba(255, 255, 255, .6); }
[data-k-surface][data-k-scheme="dark"] { --k-grid-line: rgba(76, 201, 240, .3); --k-grid-dot: rgba(76, 201, 240, .12); --k-grid-glass: rgba(16, 20, 26, .6); }

/* ───────── 1px 细线 + 毛玻璃；HUD 四角 ⌜⌟ 用渐变画 ───────── */
[data-k="panel"], [data-k="dialog"][data-k-part="content"] { border: 1px solid var(--k-grid-line); -webkit-backdrop-filter: blur(14px) saturate(1.2); backdrop-filter: blur(14px) saturate(1.2); box-shadow: 0 10px 40px rgba(0, 0, 0, .12); }
[data-k="card"] { border: 1px solid var(--k-grid-line); box-shadow: none;
  background-image: linear-gradient(var(--k-accent), var(--k-accent)), linear-gradient(var(--k-accent), var(--k-accent)), linear-gradient(var(--k-accent), var(--k-accent)), linear-gradient(var(--k-accent), var(--k-accent));
  background-repeat: no-repeat; background-size: 8px 1px, 1px 8px, 8px 1px, 1px 8px; background-position: 0 0, 0 0, 100% 100%, 100% 100%; }
[data-k="card"][data-role="choice"][data-state="selected"] { border-color: var(--k-accent); background-color: var(--k-accent-soft); }
[data-k="panel"] > [data-k-part="head"], [data-k="dialog"][data-k-part="content"] > [data-k-part="head"] { border-bottom: 1px solid var(--k-grid-line); }
[data-k="panel"] > [data-k-part="head"] > [data-k-part="title"], [data-k="dialog"][data-k-part="content"] > [data-k-part="head"] > [data-k-part="title"], [data-k="card"] > [data-k-part="head"] > [data-k-part="title"] { font-weight: 300; letter-spacing: .16em; text-transform: uppercase; }
[data-k="slider"] [data-k-part="value"], [data-k="badge"], [data-k="progress"] { font-variant-numeric: tabular-nums; }

/* ───────── 按钮：发丝框、透明底；主按钮实色 ───────── */
[data-k="button"] { font-weight: 400; letter-spacing: .12em; border-width: 1px; }
[data-k="button"]:not([data-variant="primary"]) { border-color: var(--k-grid-line); background-color: transparent; }
[data-k="button"]:active:not(:disabled), [data-k="icon-button"]:active:not(:disabled) { transform: scale(.985); }
[data-k="tabs"] [data-k-part="list"] { border-bottom: 1px solid var(--k-grid-line); }
[data-k="tabs"] [data-k-part="tab"] { letter-spacing: .12em; font-weight: 400; }
[data-k="tabs"] [data-k-part="tab"][data-state="active"] { border-bottom-color: transparent; box-shadow: inset 0 -2px 0 var(--k-accent); color: var(--k-on); }
