[data-k="slider"] > [data-k-part="track"] > [data-k-part="thumb"] { background: var(--k-bg); box-shadow: 0 0 0 2px var(--k-accent), 0 0 8px color-mix(in srgb, var(--k-accent) 50%, transparent); }
