/* 面板背景：一圈咖啡渍 + 斜着的「CASE #13」档案章 */
[data-k="panel"] > [data-k-ornament="surface-backdrop"], [data-k="dialog"][data-k-part="content"] > [data-k-ornament="surface-backdrop"] { display: block; }
