[data-k="panel"] > [data-k-ornament="surface-backdrop"]::after, [data-k="dialog"][data-k-part="content"] > [data-k-ornament="surface-backdrop"]::after { content: 'CASE #13'; position: absolute; left: 20px; bottom: 30px; padding: 4px 10px; font: 700 22px/1 "Courier Prime", var(--k-font-mono); letter-spacing: .2em; color: var(--k-noir-red); border: 3px solid var(--k-noir-red); transform: rotate(-12deg); opacity: .1; }
[data-k="msg-view"] > [data-k-ornament="surface-backdrop"] { display: block; }
[data-k="msg-view"] > [data-k-ornament="surface-backdrop"]::before { content: ''; position: absolute; right: 16px; top: 14px; width: 70px; height: 70px; border-radius: 50%; box-shadow: inset 0 0 0 2px rgba(120, 80, 40, .12); }

/* 行动选项：7 种类型各一色（左边色条 + 类型标签；标签字色与正文色混合保证对比度） */
[data-k-surface] { --k-opt-action: #d89a3c; --k-opt-persona: #9a6a8a; --k-opt-plot: #6a8a6a; --k-opt-info: #6a7a9a; --k-opt-fun: #c0a050; --k-opt-nsfw: #c03a3a; --k-opt-other: #8a8a8a; }
