/* 面板背景右下角：半身立绘，左侧与上方渐隐进底色；卡片本身有底色，立绘只在卡片之间的空隙里露出来，不压字 */
[data-k-surface][data-k-effects~="portrait"] [data-k="panel"] > [data-k-ornament="surface-backdrop"] { display: block; }
[data-k-surface][data-k-effects~="portrait"] [data-k="panel"] > [data-k-ornament="surface-backdrop"]::after { content: ''; position: absolute; right: -6px; bottom: 0; width: min(46%, 380px); aspect-ratio: 2 / 3; background: var(--k-asset-portrait) right bottom / contain no-repeat; opacity: var(--k-ai-portrait-alpha, .34); -webkit-mask: linear-gradient(90deg, transparent, #000 38%), linear-gradient(0deg, #000 70%, transparent); -webkit-mask-composite: source-in; mask: linear-gradient(90deg, transparent, #000 38%) intersect, linear-gradient(0deg, #000 70%, transparent); }
[data-k-surface][data-k-scheme="dark"] { --k-ai-portrait-alpha: .26; }
/* 手机：面板窄，立绘换成右下角一只 Q 版 */
@media (max-width: 1000px) {
  [data-k-surface][data-k-effects~="portrait"] [data-k="panel"] > [data-k-ornament="surface-backdrop"]::after { width: 120px; aspect-ratio: 1; background-image: var(--k-asset-chibi); opacity: .32; -webkit-mask: none; mask: none; }
}
/* 对话框右下角一只小 Q 版 */
[data-k-surface][data-k-effects~="portrait"] [data-k="dialog"][data-k-part="content"] > [data-k-ornament="surface-backdrop"]::after { content: ''; position: absolute; right: 6px; bottom: 6px; width: 84px; height: 84px; background: var(--k-asset-chibi) center / contain no-repeat; opacity: .5; }
/* 空状态的插图 */
[data-k="empty"] > [data-k-ornament="empty-art"] { display: block; position: relative; left: auto; translate: none; width: 96px; height: 96px; margin: 0 auto 6px; background: var(--k-asset-chibi) center / contain no-repeat; }
[data-k-surface][data-k-motion="full"] [data-k="empty"] > [data-k-ornament="empty-art"] { animation: k-ai-breathe 3.2s ease-in-out infinite; }
@keyframes k-ai-breathe { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-3px); } }
/* 场景：对话框与消息正文背景铺一层很淡的场景（从右上角渐隐），盖一层底色保证文字对比度 */
[data-k-surface][data-k-effects~="scene"] [data-k="dialog"][data-k-part="content"] > [data-k-ornament="surface-backdrop"], [data-k-surface][data-k-effects~="scene"] [data-k="msg-view"] > [data-k-ornament="surface-backdrop"] { display: block; background: var(--k-asset-scene) right top / cover no-repeat; opacity: var(--k-ai-scene-alpha, .16); -webkit-mask: radial-gradient(130% 110% at 100% 0, #000, transparent 75%); mask: radial-gradient(130% 110% at 100% 0, #000, transparent 75%); }
[data-k-surface][data-k-scheme="dark"] { --k-ai-scene-alpha: .12; }
/* 思维链 / 搜索资料标题前：Q 版表情头像（生成中 / 完成 / 查资料 / 没找到资料），换掉原来的图标 */
[data-k-surface][data-k-effects~="faces"] [data-k="msg-think"] > [data-k-part="head"] > [data-k-part="toggle"] > [data-k-ornament="state-face"][data-k-face="think"] { display: inline-block; background-image: var(--k-asset-face-think); }
[data-k-surface][data-k-effects~="faces"] [data-k="msg-think"] > [data-k-part="head"] > [data-k-part="toggle"] > [data-k-ornament="state-face"][data-k-face="done"] { display: inline-block; background-image: var(--k-asset-face-done); }
[data-k-surface][data-k-effects~="faces"] [data-k="msg-search"] > [data-k-part="head"] > [data-k-part="toggle"] > [data-k-ornament="state-face"][data-k-face="search"] { display: inline-block; background-image: var(--k-asset-face-search); }
[data-k-surface][data-k-effects~="faces"] [data-k="msg-search"] > [data-k-part="head"] > [data-k-part="toggle"] > [data-k-ornament="state-face"][data-k-face="oops"] { display: inline-block; background-image: var(--k-asset-face-oops); }
[data-k-surface][data-k-effects~="faces"] [data-k="msg-think"] > [data-k-part="head"] > [data-k-part="toggle"] > [data-k-part="icon"], [data-k-surface][data-k-effects~="faces"] [data-k="msg-search"] > [data-k-part="head"] > [data-k-part="toggle"] > [data-k-part="icon"] { opacity: 0; width: 0; min-width: 0; margin: 0 -4px 0 0; }
/* 头像放大到约 36px，垫一个强调色圆底（白发 / 浅色角色在浅色底上也立得住），用负外边距不撑高标题行 */
[data-k-surface][data-k-effects~="faces"] :is([data-k="msg-think"] > [data-k-part="head"] > [data-k-part="toggle"], [data-k="msg-search"] > [data-k-part="head"] > [data-k-part="toggle"]) > [data-k-ornament="state-face"] { width: 2.3em; height: 2.3em; margin-block: -.55em; border-radius: 50%; background-size: 108%; background-position: 50% 30%; background-color: color-mix(in srgb, var(--k-accent) var(--k-ai-plate, 14%), transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--k-accent) 30%, transparent); }
[data-k-surface][data-k-effects~="faces"][data-k-motion="full"] [data-k="msg-think"] > [data-k-part="head"] > [data-k-part="toggle"] > [data-k-ornament="state-face"][data-k-face="think"] { animation: k-ai-bob 1.4s ease-in-out infinite; }
@keyframes k-ai-bob { 0%, 100% { transform: rotate(-6deg); } 50% { transform: rotate(6deg) translateY(-1px); } }
/* 卡片右下角：标志道具小图（容器卡：单数 item-1、双数 item-2；选择卡：选中时出现 item-1）。特效开关「道具」控制 */
[data-k-surface][data-k-effects~="items"] [data-k="card"][data-role="container"] > [data-k-ornament="card-corner"] { display: block; right: 8px; bottom: 6px; width: 30px; height: 30px; background: var(--k-asset-item-1) center / contain no-repeat; opacity: .75; }
[data-k-surface][data-k-effects~="items"] [data-k="card"][data-role="choice"][data-state="selected"] > [data-k-ornament="card-corner"] { display: block; right: 6px; bottom: 4px; width: 24px; height: 24px; background: var(--k-asset-item-1) center / contain no-repeat; opacity: .9; }
/* 卡片右侧有说明文字（「默认」「已开启」）时不放，免得压字 */
[data-k-surface][data-k-effects~="items"] [data-k="card"][data-role="choice"][data-state="selected"]:has(> [data-k-part="select"] [data-k-part="meta"]) > [data-k-ornament="card-corner"] { display: none; }
[data-k-surface][data-k-effects~="items"] [data-k="card"][data-role="container"]:nth-child(even) > [data-k-ornament="card-corner"] { background-image: var(--k-asset-item-2); }

/* 行动选项：7 种类型各一色（左边色条 + 类型标签；标签字色与正文色混合保证对比度） */
[data-k-surface] { --k-opt-action: #1f3f8a; --k-opt-persona: #5a4a8a; --k-opt-plot: #2f6f5a; --k-opt-info: #2f6fa8; --k-opt-fun: #8a6a2a; --k-opt-nsfw: #a8303a; --k-opt-other: #6a6e78; }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"][data-k-type="action"] { --k-opt: var(--k-opt-action); }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"][data-k-type="persona"] { --k-opt: var(--k-opt-persona); }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"][data-k-type="plot"] { --k-opt: var(--k-opt-plot); }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"][data-k-type="info"] { --k-opt: var(--k-opt-info); }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"][data-k-type="fun"] { --k-opt: var(--k-opt-fun); }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"][data-k-type="nsfw"] { --k-opt: var(--k-opt-nsfw); }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"][data-k-type="other"] { --k-opt: var(--k-opt-other); }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"] { box-shadow: inset 3px 0 0 var(--k-opt, transparent); }
[data-k="msg-options"] > [data-k-part="fold"] > [data-k-part="list"] > li > [data-k-part="item"] > [data-k-part="item-head"] > [data-k-part="type"] > [data-k="badge"] { background: color-mix(in srgb, var(--k-opt, var(--k-accent)) 16%, transparent); color: color-mix(in srgb, var(--k-opt, var(--k-accent)) 42%, var(--k-on)); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--k-opt, var(--k-accent)) 45%, transparent); }

/* ═══════════ 存在感：角色栏 / 看板娘 / 场景横幅 / 表情与道具（docs/AI娘系列方案.md 四之二） ═══════════ */
/* 电脑：面板够宽（≥ 900px）时右侧空出一栏，立绘实心站在里面，文字不进这一栏；拖窄了退回淡水印 */
@media (min-width: 1001px) {
  [data-k-surface][data-k-effects~="stage"] [data-k="panel"][data-k-width="wide"] > [data-k-part="body"], [data-k-surface][data-k-effects~="stage"] [data-k="panel"][data-k-width="wide"] > [data-k-part="foot"] { padding-right: 252px; }
  [data-k-surface][data-k-effects~="stage"] [data-k="panel"][data-k-width="wide"] > [data-k-ornament="surface-backdrop"] { background: linear-gradient(var(--k-divider), var(--k-divider)) calc(100% - 252px) 76px / 1px calc(100% - 112px) no-repeat; }
  [data-k-surface][data-k-effects~="stage"] [data-k="panel"][data-k-width="wide"] > [data-k-ornament="surface-backdrop"]::after { right: 4px; bottom: 0; width: 244px; height: calc(100% - 64px); aspect-ratio: auto; background: var(--k-asset-portrait) center bottom / contain no-repeat; opacity: 1; -webkit-mask: linear-gradient(0deg, transparent, #000 56px); mask: linear-gradient(0deg, transparent, #000 56px); }
}
