/* 提示条：按语气换表情 */
[data-k-surface][data-k-effects~="faces"] [data-k="toast"] > [data-k-ornament="toast-face"] { display: inline-block; background-image: var(--k-asset-face-done); }
[data-k-surface][data-k-effects~="faces"] [data-k="toast"][data-k-tone="danger"] > [data-k-ornament="toast-face"] { background-image: var(--k-asset-face-oops); }
