    if (r.error) { return '检查失败：' + r.error; }
    var act = r.action;
    if (act === 'unconfigured') { return '远程更新脚本还没配置仓库'; }
    if (act === 'cooldown') { return '刚查过，还没到下次检查时间'; }
    if (act === 'none') { return '已经是最新版本' + (r.localVersion ? ('（' + r.localVersion + '）') : ''); }
