  stageDownload: '下载新版',
  stageVerify: '校验文件',
  stageMerge: '合并内容',
  stageWrite: '写入预设',
  stageDone: '更新完成',
  stageFailed: '更新失败',
  bytesOf: '已下载 {done}，共 {total}',
  bytesOnly: '当前已下载 {done}',
  indeterminate: '未能获取总大小，正在持续下载',
  retry: '重试',
  close: '关闭',
  doneHint: '更新已完成，这个窗口马上自动关闭',
