/* ────────────────────────── 内部实现 ────────────────────────── */

function cloneObj(o) {
  try {
    if (o === undefined || o === null || typeof o !== 'object') { return o; }
    return JSON.parse(JSON.stringify(o));
  } catch (e) { return o; }
}
function cleanStr(v) {
  try { return (v === undefined || v === null) ? '' : String(v).replace(/^[\s\u200B]+|[\s\u200B]+$/g, ''); }
  catch (e) { return ''; }
}
