  for (i = 0; i < list.length; i++) { out.push(cleanStr(list[i] && list[i].identifier)); }
  return out;
}
function seqEq(a, b) {
  if (!a || !b || a.length !== b.length) { return false; }
  var i;
  for (i = 0; i < a.length; i++) { if (a[i] !== b[i]) { return false; } }
  return true;
}
function arrOf(v) { return Array.isArray(v) ? v : []; }
