  if (tMainEntry) { nMainEntry = orderEntryOf(N_ORD, cleanStr(tMainEntry.character_id)); }

  /* 用 next 造合并条目（开关按 enabledOf 兜底）。 */
  function fromNextPrompt(n, tObj, tOrdItem, nOrdItem) {
