  var scriptReport = mergeScripts(
    arrOf(isPreset(tExt.tavern_helper) ? tExt.tavern_helper.scripts : []),
    arrOf(isPreset(nExt.tavern_helper) ? nExt.tavern_helper.scripts : [])
