    var name = cleanStr(oldName);
    if (!name) { return Promise.resolve({ ok: false, msg: '没给要继承的预设名' }); }
    if (busy) { return Promise.resolve({ ok: false, msg: '更新脚本正忙着（在下载或检查），稍等一下再试' }); }

    /* ★ 当前预设名**必须在动任何东西之前**抓好：写盘那一步要靠它把结果放回原处，
       而动过活设置之后再解析，万一解析层读到刚被覆盖的字段就会认成别的预设。 */
    var targetName = cleanStr(resolvePresetName().name);
    if (!targetName) {
      return Promise.resolve({ ok: false, msg: '拿不到当前预设名，不知道要把设置搬回哪一份，已中止' });
    }

    var theirs = readPresetSnapshot(name);
    if (!theirs || !Array.isArray(theirs.prompts) || !theirs.prompts.length) {
      return Promise.resolve({ ok: false, msg: '读不到「' + name + '」的内容（酒馆没把它装进内存，或者它不像一份预设）' });
    }
    if (name === targetName) {
      return Promise.resolve({ ok: false, msg: '「' + name + '」就是你现在用的这一份，没法从自己继承自己' });
    }
    var next = currentPresetSnapshot();
    if (!next || !Array.isArray(next.prompts) || !next.prompts.length) {
      return Promise.resolve({ ok: false, msg: '读不到当前预设的完整内容，做不了合并' });
    }

    var v = parseVersion(name);
    var cfg = repoConfig();
    busy = true;
    last.action = 'inherit';
    log('继承旧预设设置：theirs =「' + name + '」（' + theirs.prompts.length + ' 条）· next =「' + targetName +
      '」（' + next.prompts.length + ' 条）· base = ' + (v ? versionLabel(v) : '认不出（退化模式）'));

    return fetchBaseSnapshot(v ? versionLabel(v) : '', cfg, name).then(function (base) {
      var plan = computeMergePlan(base, theirs, next);
      plan.inherit = true;   /* 让裁决页把措辞换成「你的旧预设 / 现在这份」 */
      log('继承合并计划就绪：待裁决 ' + plan.conflicts.length + ' 处 / 新版新增 ' + plan.stats.added +
        ' 条 / 应用 ' + plan.stats.applied + ' 处' + (plan.degraded ? '（退化模式：base 取不到）' : ''));
      return decidePlan(plan).then(function (chosen) {
        if (!chosen) {
          busy = false;
          last.action = 'inherit-cancelled';
          log('你在裁决页里没有完成，本次继承中止（什么都不会写）');
          return { ok: false, cancelled: true };
        }
        var applied = applyMergePlan(base, theirs, next, chosen.plan);
        pinIdentity(applied.merged, targetName);
        return backupCurrentPreset(next).then(function (b) {
          busy = false;
          last.action = 'inherit-ready';
          last.merge = {
            degraded: !!applied.report.degraded, applied: applied.report.applied, kept: applied.report.kept,
            added: applied.report.added, conflicts: applied.report.conflicts,
            decidedMine: applied.report.decidedMine, decidedNext: applied.report.decidedNext, scriptsDeduplicated: applied.report.scriptsDeduplicated || 0
          };
          log('继承方案已就绪（' + mergeReportText(applied.report) + '；名字钉成「' + targetName +
            '」）→ 交给 40 号写回当前预设');
          return {
            ok: true, merged: completionPresetForLive(applied.merged, settingsOf(stCtx())), report: applied.report,
            oldName: name, targetName: targetName, backupName: b.backupName,
            decidedVia: chosen.via || null,
            oldPrompts: theirs.prompts.length, currentPrompts: next.prompts.length
          };
        });
      });
    })['catch'](function (e) {
      busy = false;
      var msg = (e && e.message) || String(e);
      warn('继承旧预设设置失败：' + msg);
      return { ok: false, msg: msg };
    });
  }

  /* ───────── 全局 API ───────── */

  function status() {
    return {
      version: VERSION,
      repo: repoConfig(),
      configured: repoConfig().configured,
      checks: checks,
      busy: busy,
      lastCheckedAt: last.at ? new Date(last.at).toLocaleString() : null,
      lastOk: last.ok,
      lastError: last.error,
      localPreset: last.localName,
      localVersion: last.localVersion,
      localBuild: last.localBuild,
      remote: last.remote,
      lastAction: last.action,
      skipped: vars ? vars.skipped : '',
      imported: vars ? vars.imported : '',
      lastMerge: last.merge,
      logs: LOGS.slice(-30)
    };
  }

  function expose() {
    var api = {
      version: VERSION,
      __instance: INSTANCE_ID,   /* 注销时只删“自己这一份”的判据（见 INSTANCE_ID 的注释） */
      status: status,
      /* ── 「本机是哪个版本」的对外读取口（2026-09-26 用户点名要的）──
         版本号的唯一真相是仓库根目录的 version.json，构建时把正式分发名写进脚本文本（SELF_NAME）；
         别的脚本想拿版本可以读这里，**但不要把它当成必须**：本脚本可能被用户关掉，
         所以 40 号 / 50 号各自也有一份构建期常量，读不到这里照样知道自己是哪一版。 */
      selfName: function () { return SELF_NAME; },
      presetVersion: function () {
        var v = parseVersion(SELF_NAME);
        return { name: SELF_NAME, label: v ? versionLabel(v) : '', build: v ? v.build : null, date: v ? v.date : '' };
      },
      /* 手动查一次；force=true 时忽略「已拒绝/已写入/已安装」记录 */
      check: function (force) { return check(!!force); },
      /* ── 「继承旧预设设置」（2026-09-28 用户点名，给手动更新的用户兜底）──
         面板那条链路：otherPresetNames() 摆清单 → isKamiName() 决定要不要先警告 →
         inheritFrom(名) 跑同一台合并引擎（结果由 40 号写回当前预设）。 */
      otherPresetNames: otherPresetNames,
      isKamiName: isKamiName,
      inheritFrom: inheritFrom,
      /* 清掉「拒绝过 / 已写入」的记录（下次启动会重新弹） */
      reset: function () {
        saveVars({ skipped: '', imported: '' });
        log('已清空版本记录');
        return status();
      },
      shutdown: function () { teardown(); }
    };
    try { HOST[API_NAME] = api; } catch (e) { }
    try { window[API_NAME] = api; } catch (e) { }
  }

  /* ───────── 注销（零残留） ───────── */

  function teardown() {
    if (disposed) { return; }
    disposed = true;
    if (stopResolve) { stopResolve(); stopResolve = null; }
    if (calmResolve) { calmResolve(last); calmResolve = null; }
    activeRequests.forEach(function (ctrl) { try { ctrl.abort(); } catch (e) { } }); activeRequests.clear();
    try { closeProgress(); } catch (e) { }
    try { window.removeEventListener('pagehide', hideHandler); } catch (e) { }
    try { if (HOST !== window) { HOST.removeEventListener('pagehide', hideHandler); } } catch (e) { }
    hideHandler = null;
    log('正在注销：停定时器 / 删全局 API');
    var i;
    while (timers.length) { hclear(timers[timers.length - 1]); }
    timers = [];
    hclear(calmTimer);
    calmTimer = null;
    /* ★ 只删“自己这一份”：旧实例的 pagehide 迟到时，全局可能已经是新实例的了，不能动。 */
    try { if (HOST[API_NAME] && HOST[API_NAME].__instance === INSTANCE_ID) { delete HOST[API_NAME]; } } catch (e) { }
    try { if (window[API_NAME] && window[API_NAME].__instance === INSTANCE_ID) { delete window[API_NAME]; } } catch (e) { }
    /* 启动声明同样只清自己的：不清的话，30 秒内重挂的新实例会被旧声明挡在门外直接退出。 */
    try { var c = HOST.__kamiUpdateClaim; if (c && c.id === INSTANCE_ID) { delete HOST.__kamiUpdateClaim; } } catch (e) { }
    log('注销完成：进度窗口、样式、监听与定时器已收回');
  }

  /* 启动时的自动检查：受 6 小时间隔保护（未认证 API 按 IP 限流，用户常聚同一出口 IP）。
     手动 KamiUpdate.check() 不受此限，随时可以查。 */
  function autoCheck() {
    var intervalMs = CHECK_INTERVAL_HOURS * 3600 * 1000;
    if (vars.lastCheckAt && (Date.now() - vars.lastCheckAt) < intervalMs) {
      last.action = 'cooldown';
      log('距上次检查不满 ' + CHECK_INTERVAL_HOURS + ' 小时，本次启动不连网（KamiUpdate.check() 可手动查）');
      return Promise.resolve(last);
    }
    return check(false);
  }

  /* ───────── 启动 ───────── */

  /* 同一窗口里出现两份同名脚本时，只让先启动的那份跑（弹窗只会弹一次） */
  function claimInstance() {
    var prev = null;
    try { prev = HOST.__kamiUpdateClaim; } catch (e) { }
    var now = Date.now();
    if (prev && prev.bootAt && (now - prev.bootAt) < DEDUPE_MS && prev.id !== INSTANCE_ID) {
      log('已有另一个「🔄 远程更新」实例在 ' + Math.round((now - prev.bootAt) / 1000) + 's 前启动，本实例退出（脚本库里是不是有两份？）');
      return false;
    }
    try { HOST.__kamiUpdateClaim = { bootAt: now, id: INSTANCE_ID }; } catch (e) { }
    return true;
  }

  function boot() {
    log('启动 v' + VERSION + '（纯后台脚本，没有按钮）');
    if (!claimInstance()) { disposed = true; return; }
    readVars();
    expose();
    var cfg = repoConfig();
    if (!cfg.configured) {
      log('尚未配置 GitHub 仓库：等仓库建好后填上 REPO_OWNER / REPO_NAME 再重新构建即可');
    }
    /* 稍等几秒再做第一次检查：让向导、皮肤、面板先就绪，弹窗不跟它们抢 */
    hsetTimeout(function () { autoCheck(); }, BOOT_DELAY);
    /* 页面只是**进 BFCache**（手机上切后台 / 返回上一页，persisted=true）时不注销：
       这种情况下脚本 iframe 活得好好的，回来还要用；注销了就没有任何东西能唤醒。
       只有真卸载（persisted=false / undefined）才走注销。 */
    hideHandler = function (ev) { try { if (ev && ev.persisted) { return; } teardown(); } catch (e) { } };
    try {
      window.addEventListener('pagehide', hideHandler);
      if (HOST !== window) { HOST.addEventListener('pagehide', hideHandler); }
    } catch (e) { }
  }

  try { boot(); } catch (e) { warn('启动失败：' + ((e && e.message) || e)); }

  /* ============================================================
   * 发布约定（发新版本时按这个来）
   * ------------------------------------------------------------
   * 分发走 GitHub Releases，发新版 = 在仓库页发一个 Release：
   *   ① 附件上传正式分发文件，文件名即版本号来源：
   *      卡密预设v{大版本号}.{两位小版本号}-{构建号}-{日期}.json
   *      例如 卡密预设v0.90-<构建号>-<日期>.json（日期 8 位，年在前）
   *   ② Release 说明正文 = 弹窗里的更新说明（纯文本，一行一条）；
   *      不要放 | { } \ 四个字符（弹窗管道符与宏语法要用，放了会被自动换成全角）
   *   ③ 别发草稿；预发布（prerelease）算正式版，开发期可以直接发
   * 用户下次启动酒馆（默认 6 小时检查一次）就会看到更新弹窗。
   * ============================================================ */
})();

